134	const makeChainable = (table: string, itensData = mockItens) => {
135	  const chainable: any = {
136	    select: vi.fn(() => chainable),
137	    eq: vi.fn(() => chainable),
138	    order: vi.fn(() => chainable),
139	    limit: vi.fn(() => chainable),
140	    in: vi.fn(() => chainable),
141	    not: vi.fn(() => chainable),
142	    ilike: vi.fn(() => chainable),
143	    or: vi.fn(() => chainable),
144	    gt: vi.fn(() => chainable),
145	    gte: vi.fn(() => chainable),
146	    lte: vi.fn(() => chainable),
147	    update: vi.fn(() => chainable),
148	    insert: vi.fn(() => chainable),
149	    delete: vi.fn(() => chainable),
150	    maybeSingle: vi.fn(() => Promise.resolve({ data: null, error: null })),
151	    single: vi.fn(() =>
152	      Promise.resolve({
153	        data: table === 'requisicoes' ? mockReqInfo : itensData[0],
154	        error: null,
155	      }),
156	    ),
157	    then: (resolve: any) => {
158	      if (table === 'requisicoes')
159	        return resolve({ data: mockReqInfo, error: null });
160	      if (table === 'requisicoes_itens')
161	        return resolve({ data: itensData, error: null });
162	      if (table === 'profiles')
163	        return resolve({
164	          data: { nome: 'Mock User', username: 'mockuser' },
165	          error: null,
166	        });
167	      if (table === 'expedicao_logs') return resolve({ data: [], error: null });
168	      return resolve({ data: [], error: null });
169	    },
170	  };
171	  return chainable;
172	};
