1536	  const updateManualQuantity = (itemId: number, value: string) => {
1537	    const item = itens.find((i) => i.id === itemId);
1538	    if (!item) return;
1539	
1540	    // Validação: rejeitar quantidades negativas
1541	    const numValue = parseFloat(value);
1542	    if (Number.isFinite(numValue) && numValue < 0) {
1543	      toast({
1544	        title: 'Quantidade inválida',
1545	        description: 'A quantidade não pode ser negativa.',
1546	        variant: 'destructive',
1547	      });
1548	      return;
1549	    }
1550	
1551	    // Normaliza o valor: string vazia permitida, NaN vira "0"
1552	    const sanitizedValue =
1553	      value === ''
1554	        ? ''
1555	        : Number.isFinite(numValue)
1556	          ? String(Math.max(0, numValue))
1557	          : '0';
1558	
1559	    const prevValue = item.quantidade_enviada || '';
1560	
1561	    // Atualização otimista da UI
1562	    setItens((prev) =>
1563	      prev.map((i) =>
1564	        i.id === itemId ? { ...i, quantidade_enviada: sanitizedValue } : i,
1565	      ),
1566	    );
1567	
1568	    // Debounce por item para evitar flood de writes enquanto o usuário digita
1569	    const existingTimer = manualQuantityTimers.current.get(itemId);
1570	    if (existingTimer) clearTimeout(existingTimer);
1571	
1572	    const timer = setTimeout(async () => {
1573	      manualQuantityTimers.current.delete(itemId);
1574	      try {
1575	        const { error: updateError } = await supabase
1576	          .from('requisicoes_itens' as any)
1577	          .update({ quantidade_enviada: sanitizedValue })
1578	          .eq('id', itemId);
1579	
1580	        if (updateError) throw updateError;
1581	
1582	        // Log apenas mudanças significativas (>=1 unidade) após sucesso
1583	        if (
1584	          user &&
1585	          Math.abs((parseFloat(sanitizedValue || '0') || 0) - (parseFloat(prevValue || '0') || 0)) >= 1
1586	        ) {
1587	          const nomeUser = myProfileName;
1588	          const nomeProd = item.produto_nome || 'Item';
1589	          const color = colorForUser(user.id);
1590	          const actionText = `${nomeUser} alterou quantidade de ${nomeProd} para ${sanitizedValue} uni`;
1591	          channelRef.current?.send({
1592	            type: 'broadcast',
1593	            event: 'user_event',
1594	            payload: { text: actionText, color },
1595	          });
1596	          pushLog(actionText, color);
1597	        }
1598	      } catch (e) {
1599	        // Rollback otimista
1600	        setItens((prev) =>
1601	          prev.map((i) =>
1602	            i.id === itemId ? { ...i, quantidade_enviada: prevValue } : i,
1603	          ),
1604	        );
1605	        handleError(e, { domain: 'requisicoes', operation: 'updateManualQuantity', showToast: false });
1606	        toast({
1607	          title: 'Erro ao salvar',
1608	          description: 'Não foi possível atualizar a quantidade. Tente novamente.',
1609	          variant: 'destructive',
1610	        });
1611	      }
1612	    }, 400); // 400ms debounce
1613	
1614	    manualQuantityTimers.current.set(itemId, timer);
1615	  };
