173	function injectIOSToolbar(fullHTML: string, title: string): string {
174	  // Inject CSS into <head>
175	  let out = fullHTML.replace(/<\/head>/i, `${IOS_TOOLBAR_CSS}</head>`);
176	  if (!/<\/head>/i.test(fullHTML)) {
177	    // No </head> — inject at start
178	    out = `${IOS_TOOLBAR_CSS}${out}`;
179	  }
180	  // Inject toolbar right after <body> opening tag
181	  out = out.replace(/<body([^>]*)>/i, `<body$1>${IOS_TOOLBAR_HTML}`);
182	  if (!/<body[\s>]/i.test(out)) {
183	    // No <body> — prepend toolbar
184	    out = `${IOS_TOOLBAR_HTML}${out}`;
185	  }
186	  // Ensure title
187	  if (!/<title>/i.test(out)) {
188	    out = out.replace(/<head>/i, `<head><title>${escapeHTML(title)}</title>`);
189	  }
190	  return out;
191	}
192	
193	function downloadAsHTML(html: string, title: string) {
194	  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
195	  const url = URL.createObjectURL(blob);
196	  const a = document.createElement('a');
197	  a.href = url;
198	  a.download = `${sanitizeFileName(title)}.html`;
199	  document.body.appendChild(a);
200	  a.click();
201	  document.body.removeChild(a);
202	  setTimeout(() => URL.revokeObjectURL(url), 1000);
203	}
204	
205	function sanitizeFileName(s: string): string {
206	  return s.replace(/[^a-zA-Z0-9\-_. ]/g, '_').trim() || 'impressao';
207	}
208	
209	function escapeHTML(s: string): string {
210	  return s
211	    .replace(/&/g, '&amp;')
212	    .replace(/</g, '&lt;')
213	    .replace(/>/g, '&gt;')
214	    .replace(/"/g, '&quot;')
215	    .replace(/'/g, '&#39;');
216	}
